<?php
require "db.php";require "functions.php";need_role("student");$id=(int)$_SESSION["user_id"];
$q=$pdo->prepare("SELECT COUNT(*) total,SUM(status='Submitted') submitted,SUM(status='In Progress') progress,SUM(status='Resolved') resolved FROM complaints WHERE student_id=?");$q->execute([$id]);$s=$q->fetch();
$q=$pdo->prepare("SELECT id,title,category,status,created_at FROM complaints WHERE student_id=? ORDER BY created_at DESC LIMIT 8");$q->execute([$id]);$rows=$q->fetchAll();
$title="Student dashboard";require "layout.php";?>
<div class="page-heading"><div><div class="eyebrow">STUDENT WORKSPACE</div><h1>Hello, <?=e($_SESSION["user_name"])?> <span class="green">✳</span></h1><p>Here is what is happening with your campus reports.</p></div><a class="btn btn-primary" href="complaint.php">＋ New complaint</a></div>
<div class="stat-grid"><div class="stat-card"><small>Total reports</small><strong><?= (int)($s["total"]??0)?></strong><span>Submitted by you</span></div><div class="stat-card"><small>Awaiting review</small><strong><?= (int)($s["submitted"]??0)?></strong><span>Recently submitted</span></div><div class="stat-card"><small>In progress</small><strong><?= (int)($s["progress"]??0)?></strong><span>Being worked on</span></div><div class="stat-card"><small>Resolved</small><strong><?= (int)($s["resolved"]??0)?></strong><span>Marked complete</span></div></div>
<section class="panel"><div class="panel-heading"><div><h2>Your recent complaints</h2><p>Only you can see your reports.</p></div><a class="text-link" href="my_complaints.php">View all ↗</a></div><?php if(!$rows):?><div class="empty"><h3>Your story starts here</h3><p>You have not submitted a complaint yet.</p><a class="btn btn-primary" href="complaint.php">Submit your first report</a></div><?php else:?><div class="table-wrap"><table><thead><tr><th>Complaint</th><th>Category</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r["title"])?></b><div class="muted small">#<?= (int)$r["id"]?></div></td><td><?=e($r["category"])?></td><td><?=status_badge($r["status"])?></td><td><?=e(date("M j, Y",strtotime($r["created_at"])))?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
